把map[string]string 把它看做是一个对象
map等价于{}对象，[string]string等价于key:value的形式
因为map中读取是obje["key"]，所以key的声明在括号里
整体如下：
{
key:value的形式，key是字符串，value也是字符串
}
make([]map[string]string,3,3)
就等价于
make([]{
key:value的形式，key是字符串，value也是字符串
})
切片定义一个对象数组
要定于对象数组，外层肯定是切片，内层是map
map[string]string => { key:value }
[]map[string]string => [{ key:value }]
package main
import ("fmt")

func main()  {
	var mapObject = make([]map[string]string,2,2)
	fmt.Println(mapObject[0]== nil)
	if mapObject[0] == nil {
		mapObject[0] = make(map[string]string)
		mapObject[0]["name"] = "xiaoming"
		mapObject[0]["age"] = "18"
	}
	if mapObject[1] == nil {
		mapObject[1] = make(map[string]string)
		mapObject[1]["name"] = "xiaohong"
		mapObject[1]["age"] = "19"
	}
	fmt.Println(mapObject)
} 

[map[age:18 name:xiaoming] map[age:19 name:xiaohong]]
